}

/* 巨大な土台の炎 (オレンジから消えていく) */
.flame-base {
    position: absolute;
    bottom: -30%;
    left: 50%;
    transform: translateX(-50%);
    width: 110%;
    height: 58%;
    background: radial-gradient(
        ellipse at 50% 100%,
        rgba(255, 200, 100, 0.55) 0%,
        rgba(243, 128, 32, 0.4) 18%,
        rgba(199, 62, 29, 0.25) 38%,
        rgba(80, 20, 10, 0.15) 60%,
        transparent 80%
    );
    filter: blur(50px);
    animation: flicker-base 5.5s ease-in-out infinite alternate;
    pointer-events: none;
}

/* 中段の炎 (左寄り) */
.flame-mid {
    position: absolute;
    bottom: -10%;
    left: 25%;
    width: 55%;
    height: 45%;
    background: radial-gradient(
        ellipse at 50% 100%,
        rgba(255, 230, 150, 0.7) 0%,
        rgba(251, 173, 65, 0.45) 25%,
        rgba(243, 128, 32, 0.25) 50%,
        transparent 75%
    );
    filter: blur(35px);
    mix-blend-mode: screen;
    animation: flicker-mid 4.2s ease-in-out infinite alternate;
    pointer-events: none;
}

/* 上段の炎 (右寄り、明るめのコア) */
.flame-top {
    position: absolute;
    bottom: -5%;
    left: 50%;
    width: 45%;
    height: 38%;
    background: radial-gradient(
        ellipse at 50% 100%,
        rgba(255, 255, 220, 0.55) 0%,
        rgba(255, 200, 100, 0.4) 30%,
        rgba(243, 128, 32, 0.15) 60%,
        transparent 80%
    );
    filter: blur(28px);
    mix-blend-mode: screen;
    animation: flicker-top 3.6s ease-in-out infinite alternate;
    pointer-events: none;
}

/* 火の粉 (天に上る粒子) */
.ember {
    position: absolute;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: rgba(255, 200, 100, 0.85);
    box-shadow: 0 0 6px 2px rgba(243, 128, 32, 0.6);
    pointer-events: none;
}

